<dialog class="app-dialog" id="confirm-dialog" aria-labelledby="confirm-title"><div class="dialog-head"><span class="state-illustration"><x-icon name="shield" :size="24"/></span><button type="button" class="icon-button" data-close-dialog aria-label="{{ ui_text('common.copy.close_dialog') }}"><x-icon name="close"/></button></div><h2 id="confirm-title">{{ ui_text('common.copy.confirm_action') }}</h2><p id="confirm-description" class="muted"></p><form id="confirm-form"><x-form-field id="confirm-reason-wrap" label="Reason"><textarea name="reason" id="confirm-reason" rows="3" required placeholder="{{ ui_text('common.copy.explain_the_reason_for_this_change') }}"></textarea></x-form-field><div class="dialog-note"><x-icon name="history" :size="16"/><span>{{ ui_text('common.copy.changes_are_validated_and_recorded_by_the_server') }}</span></div><div class="dialog-actions"><x-button variant="secondary" data-close-dialog>{{ ui_text('common.copy.cancel') }}</x-button><x-button type="submit" id="confirm-submit">{{ ui_text('common.copy.confirm') }}</x-button></div></form></dialog>
